G=load()
inp=G['Demo pair 1 input']; out=G['Demo pair 1 output']
def solve(g):
    h,w=len(g),len(g[0])
    from collections import Counter
    cnt=Counter(x for row in g for x in row if x!=9)
    blk=max(cnt,key=lambda k:(cnt[k],k))
    odds=[(r,c) for r in range(h) for c in range(w) if g[r][c]!=9 and g[r][c]!=blk]
    g2=[row[:] for row in g]
    dirs=[(-1,-1),(-1,1),(1,-1),(1,1)]
    for s in odds:
        for d in dirs:
            r,c=s; ok=True; path=[]
            while True:
                r+=d[0]; c+=d[1]
                if not(0<=r<h and 0<=c<w): ok=False;break
                if g[r][c]==blk: break
                if g[r][c]!=9 and g[r][c]!=blk and (r,c)!=s: ok=False;break
                path.append((r,c))
            if ok and g[r][c]==blk:
                # bounce point = last free cell before block
                bp=path[-1]
                # decide face: left neighbor block -> vertical hit -> flip dc; top/bottom neighbors block -> horizontal -> flip dr
                if g2[bp[0]][bp[1]-1]==blk: nd=(d[0],-d[1])
                elif g2[bp[0]][bp[1]+1]==blk: nd=(d[0],-d[1])
                elif g2[bp[0]-1][bp[1]]==blk: nd=(-d[0],d[1])
                elif g2[bp[0]+1][bp[1]]==blk: nd=(-d[0],d[1])
                else: nd=(-d[0],-d[1])
                rr,cc=bp
                while True:
                    rr+=nd[0]; cc+=nd[1]
                    if not(0<=rr<h and 0<=cc<w): break
                    if g2[rr][cc]==blk: break
                    g2[rr][cc]=3
                return g2, s,d,bp,nd
