# Hypothesis: find odd color cells, line through them, ray away from block, one optional bounce, stop at edge
def solve_variant(g,bounce=True):
    h,w=len(g),len(g[0])
    cnt=Counter(v for row in g for v in row); bg=cnt.most_common(1)[0][0]
    best=None
    for c in [x for x in cnt if x!=bg]:
        for comp in comps(g,c):
            if best is None or len(comp)>best[0]: best=(len(comp),c,comp)
    bset=set(best[2]); blk_c=best[1]
    odds=[(r,c) for r in range(h) for c in range(w) if g[r][c]!=bg and g[r][c]!=blk_c]
    # unit direction along odd line: from first to last odd sorted by r+c
    o=odds[0]; p=odds[-1]
    d=(p[0]-o[0],p[1]-o[1]); g_=math.gcd(abs(d[0]),abs(d[1]))
    u=(d[0]//g_,d[1]//g_)
    # pick direction away from block centroid
    cy=sum(r for r,c_ in bset)/len(bset); cx=sum(c_ for r,c_ in bset)/len(bset)
    def dot(d): return d[0]*(o[0]-cy)+d[1]*(o[1]-cx)
    if dot(u)<0: u=(-u[0],-u[1])
    rr,cc=o; bounced=False; cur=u
    out=[row[:] for row in g]
    while True:
        nr,nc=rr+cur[0],cc+cur[1]
        if not(0<=nr<h and 0<=nc<w): break
        if (nr,nc) in bset:
            if bounced: break
            cur=(-cur[0],-cur[1]) if abs(cur[0])>=abs(cur[1]) else (cur[0],-cur[1])
            if cur==(0,0): break
            bounced=True; continue
        if out[nr][nc]!=bg: break
        out[nr][nc]=3; rr,cc=nr,nc
    return out

