                for f in ((nd[0],-nd[1]),(-nd[0],nd[1])):
                    q=(cur[0]+f[0],cur[1]+f[1])
                    if 0<=q[0]<H and 0<=q[1]<W and q not in blk:
                        ok=True; nd=f; break
                if not ok: break
            else:
                cur=nxt; painted.add(cur); o[cur[0]][cur[1]]=3
        return painted,nd
    # find extreme endpoints of the seed diagonal
    pts=sorted([(r,c) for r in range(H) for c in range(W) if g[r][c]!=bg])
    minp=pts[0]; maxp=pts[-1]
    d=(maxp[0]-minp[0],maxp[1]-minp[1]); g2=math.gcd(abs(d[0]),abs(d[1])); d=(d[0]//g2,d[1]//g2)
    out=set()
    for st,sgn in [(minp,1),(maxp,-1)]:
        p,nd=walk(st,(d[0]*sgn,d[1]*sgn),set())
        out|=p
    return o
for i in [1,2,3,4]:
    print(i, solve(G[f'Demo pair {i} input'])==G[f'Demo pair {i} output'])

